const APP_SHELL=['./index.html','./manifest.webmanifest','./assets/pwa/icon-192.png','./assets/pwa/icon-512.png'];
const workerBase=self.registration?.scope||self.location.href||self.location.origin+'/';
const absolute=url=>new URL(url,workerBase).href;
const runtimeURLs=RUNTIME_FILES.map(file=>absolute(file.cacheUrl||file.url));
