  if(!match[1]&&match[2]){start=Math.max(0,size-Number(match[2]));end=size-1;}
  if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||start>=size||start>end)
    return new Response(null,{status:416,headers:{'Content-Range':`bytes */${size}`}});
  end=Math.min(end,size-1);
  return new Response(bytes.slice(start,end+1),{status:206,statusText:'Partial Content',headers:{
    'Accept-Ranges':'bytes','Content-Length':String(end-start+1),'Content-Range':`bytes ${start}-${end}/${size}`,
    'Content-Type':cached.headers.get('Content-Type')||'audio/mpeg'}});
